struct Ids { map:Vec<i32>,objects:Vec<H> }
impl Ids {
    fn new(size:usize)->Self {Self {map:vec![-1;size],objects:Vec::new()}}
    fn add(&mut self,h:H) {if h!=NONE && self.map[h as usize]<0 {self.objects.push(h);self.map[h as usize]=self.objects.len() as i32;}}
    fn id(&self,h:H)->i32 {if h==NONE {0} else {self.map[h as usize]}}
}
fn spikes<R:Real>(s:&mut String,p:&str,o:&Special<R>,bi:&Ids,ji:&Ids) {
    let total=o.impaled_joints.iter().filter(|h|**h!=NONE).count();let counts=o.impaled_counts.iter().filter(|n|**n!=0).count();
    let unknown=(0..MAX_BODIES).filter(|i|bi.map[*i]<0 && (o.impaled_joints[*i]!=NONE || o.impaled_counts[*i]!=0)).count();
    write!(s,"{p}joint_count={total};{p}count_count={counts};{p}unknown_keys={unknown};").unwrap();
    for h in &bi.objects {let j=o.impaled_joints[*h as usize];let count=o.impaled_counts[*h as usize];if j!=NONE || count!=0 {write!(s,"{p}impaled[{}].joint={};{p}impaled[{}].count={count};",bi.id(*h),ji.id(j),bi.id(*h)).unwrap();}}
}
pub fn level_string<R:Real>(ctx:&Ctx<R>)->String {
    let l=&ctx.level;let w=&ctx.world;let mut objects=Vec::new();let mut roots:Vec<(&str,Vec<H>)>=Vec::new();
    roots.push(("actions",l.actions.entries[..l.actions.len as usize].to_vec()));
    roots.push(("removals",l.removals.entries[..l.removals.len as usize].to_vec()));
    // Mine removes its paint root immediately after queuing action removal. A later
    // action can abort before that removal is consumed, so body liveness is insufficient.
    roots.push(("passive",(0..l.count).filter(|i|l.specials[*i as usize].kind==SpecialKind::Van || (l.specials[*i as usize].kind==SpecialKind::Mine && !l.removals.contains(*i as H) && (l.actions.contains(*i as H) || (l.specials[*i as usize].shape!=NONE && w.shape(l.specials[*i as usize].shape).handlers[3]==*i as u32+1)))).map(|i|i as H).collect()));
    roots.push(("finish",(0..l.count).filter(|i|l.specials[*i as usize].kind==SpecialKind::FinishLine).map(|i|i as H).collect()));
    for (_,array) in &roots {for h in array {if !objects.contains(h) {objects.push(*h);}}}
    let mut bi=Ids::new(MAX_BODIES);let mut si=Ids::new(MAX_SHAPES);let mut ji=Ids::new(MAX_JOINTS);
    let mut h=w.body_list;while h!=NONE {bi.add(h);let b=w.body(h);let mut sh=b.shape_list;while sh!=NONE {si.add(sh);sh=w.shape(sh).next;}h=b.next;}
    h=w.joint_list;while h!=NONE {ji.add(h);h=w.joint(h).next;}
    for h in &objects {let o=&l.specials[*h as usize];match o.kind {
        SpecialKind::Mine=>roots_mine(o,&mut bi,&mut si,&mut ji),
        SpecialKind::Van=>roots_van(o,&mut bi,&mut si,&mut ji),
        SpecialKind::SpringBox=>roots_springbox(o,&mut bi,&mut si,&mut ji),
        SpecialKind::WreckingBall=>roots_wreckingball(o,&mut bi,&mut si,&mut ji),
        SpecialKind::Fan=>roots_fan(o,&mut bi,&mut si,&mut ji),
        SpecialKind::Boost=>roots_boost(o,&mut bi,&mut si,&mut ji),
        SpecialKind::Spikes=>roots_spikes(o,&mut bi,&mut si,&mut ji),
        SpecialKind::FinishLine=>roots_finishline(o,&mut bi,&mut si,&mut ji),
        _=>panic!("unobserved special"),}}
    for h in &objects {let o=&l.specials[*h as usize];if o.kind==SpecialKind::Spikes {for b in &bi.objects {ji.add(o.impaled_joints[*b as usize]);}}}
    let mut s=String::new();write!(s,"level.body={};",bi.id(l.level_body)).unwrap();
    for (name,array) in roots {write!(s,"{name}.len={};",array.len()).unwrap();for (k,h) in array.iter().enumerate() {write!(s,"{name}[{k}]={};",objects.iter().position(|v|v==h).unwrap()).unwrap();}}
    write!(s,"objects.len={};",objects.len()).unwrap();
    for (k,h) in objects.iter().enumerate() {let o=&l.specials[*h as usize];let p=format!("objects[{k}].");match o.kind {
        SpecialKind::Mine=>state_mine(&mut s,&p,ctx,o,&bi,&si,&ji),
        SpecialKind::Van=>state_van(&mut s,&p,ctx,o,&bi,&si,&ji),
        SpecialKind::SpringBox=>state_springbox(&mut s,&p,ctx,o,&bi,&si,&ji),
        SpecialKind::WreckingBall=>state_wreckingball(&mut s,&p,ctx,o,&bi,&si,&ji),
        SpecialKind::Fan=>state_fan(&mut s,&p,ctx,o,&bi,&si,&ji),
        SpecialKind::Boost=>state_boost(&mut s,&p,ctx,o,&bi,&si,&ji),
        SpecialKind::Spikes=>state_spikes(&mut s,&p,ctx,o,&bi,&si,&ji),
        SpecialKind::FinishLine=>state_finishline(&mut s,&p,ctx,o,&bi,&si,&ji),
        _=>panic!("unobserved special"),}}s
}

/// Ordinary UserLevel ADD presence. Live shapes use the physics list order;
/// count includes retained keys outside the live lists, whose identity is not yet observed.
pub fn level_add_string<R:Real>(ctx:&Ctx<R>)->String {
    let mut s=format!("count={};",ctx.level.contact_adds.iter().filter(|v|(**v).get()).count());
    let mut body=ctx.world.body_list;let mut index=0;
    while body!=NONE {
        let mut shape=ctx.world.body(body).shape_list;
        while shape!=NONE {
            index+=1;
            if ctx.world.shape(shape).handlers[0]==crate::game::level::LEVEL_ADD_HANDLER {
                write!(s,"{index}={};",ctx.level.contact_adds[shape as usize].word()).unwrap();
            }
            shape=ctx.world.shape(shape).next;
        }
        body=ctx.world.body(body).next;
    }
    s
}
